                                                                                                                                                                                                                                                                                                                                                                                        
  CREATE OR REPLACE FORCE EDITIONABLE VIEW "MPF_USER_BASIC_V" ("EXT_USER_ID", "TENANT_ID", "SYNC_USER_ID", "UNIONID", "TITLE", "NAME", "AVATAR", "STATE_CODE", "MOBILE", "JOB_NUMBER", "EMAIL", "IS_LEAVE", "HIRED_DATE", "JOB_LEVEL_CODE", "JOB_LEVEL", "EXT_ORG_ID", "EXT_ORG_NAME", "LEADER_SYNC_USER_ID", "LEADER_EXT_USER_ID", "IS_MAIN_WORKER", "BASE_DEPT_ID") AS     
  SELECT UO.USER_ID                      AS EXT_USER_ID,                                                                                                                                                                                                                                                                                                                                
       UO.TENANT_ID,                                                                                                                                                                                                                                                                                                                                                                    
       UO.EXTRA_USER_ID                AS SYNC_USER_ID,                                                                                                                                                                                                                                                                                                                                 
       UO.UNION_ID                     AS UNIONID,                                                                                                                                                                                                                                                                                                                                      
       UO.TITLE,                                                                                                                                                                                                                                                                                                                                                                        
       UO.NAME,                                                                                                                                                                                                                                                                                                                                                                         
       UO.AVATAR,                                                                                                                                                                                                                                                                                                                                                                       
       UO.STATE_CODE,                                                                                                                                                                                                                                                                                                                                                                   
       UO.MOBILE,                                                                                                                                                                                                                                                                                                                                                                       
       UO.JOB_NUMBER,                                                                                                                                                                                                                                                                                                                                                                   
       UO.EMAIL,                                                                                                                                                                                                                                                                                                                                                                        
       UO.IS_LEAVE,                                                                                                                                                                                                                                                                                                                                                                     
       UO.HIRED_DATE,                                                                                                                                                                                                                                                                                                                                                                   
       NVL(UDP.JOB_LEVEL_CODE, 50)     as JOB_LEVEL_CODE,                                                                                                                                                                                                                                                                                                                               
       NVL(UDP.JOB_LEVEL, 'KEY_STAFF') as JOB_LEVEL,                                                                                                                                                                                                                                                                                                                                    
       UO.DEPT_ID                      AS EXT_ORG_ID,                                                                                                                                                                                                                                                                                                                                   
       UO.DEPT_NAME                    AS EXT_ORG_NAME,                                                                                                                                                                                                                                                                                                                                 
       uo.LEADER_EXTRA_USER_ID         AS LEADER_SYNC_USER_ID,                                                                                                                                                                                                                                                                                                                          
       uo.LEADER_USER_ID               AS LEADER_EXT_USER_ID,                                                                                                                                                                                                                                                                                                                           
       NVL(UP.IS_MAIN_WORKER, 0)       AS IS_MAIN_WORKER,                                                                                                                                                                                                                                                                                                                               
       UO.BASE_DEPT_ID                                                                                                                                                                                                                                                                                                                                                                  
FROM MPF_SHARE_BASIC_USER_INFO_V UO                                                                                                                                                                                                                                                                                                                                                     
         LEFT JOIN YWJA.BAO_USER_EXPAND UP ON UP.USER_ID = UO.USER_ID AND UP.TENANT_ID = UO.TENANT_ID                                                                                                                                                                                                                                                                                   
         LEFT JOIN YWJA.BAO_USER_DEPT_EXPAND UDP                                                                                                                                                                                                                                                                                                                                        
                   ON UDP.USER_ID = UO.USER_ID and UDP.DEPT_ID = UO.DEPT_ID AND UDP.TENANT_ID = UO.TENANT_ID                                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                                                                                                                                                        
where UO.MAIN_DEPT_ORDER = 0                                                                                                                                                                                                                                                                                                                                                            
  and UO.IS_LEAVE = 0;                                                                                                                                                                                                                                                                                                                                                                  

